CREATE TABLE "fonte_leitos" ("comp" TEXT NOT NULL, "uf" TEXT NOT NULL, "leitos_existentes" INTEGER NOT NULL, "leitos_sus" INTEGER NOT NULL, "uti_total_exist" INTEGER NOT NULL, "uti_total_sus" INTEGER NOT NULL, PRIMARY KEY ("comp", "uf"));
CREATE TABLE "fonte_equipes" ("unidade_da_federacao" TEXT NOT NULL, "tipo_da_equipe" TEXT NOT NULL, "quantidade" INTEGER NOT NULL, PRIMARY KEY ("unidade_da_federacao", "tipo_da_equipe"));
CREATE TABLE "fonte_servicos" ("unidade_da_federacao" TEXT NOT NULL, "classificacao_do_servico" TEXT NOT NULL, "quantidade" INTEGER NOT NULL, PRIMARY KEY ("unidade_da_federacao", "classificacao_do_servico"));
CREATE TABLE "fonte_profissionais" ("unidade_da_federacao" TEXT NOT NULL, "atende_no_sus" TEXT NOT NULL, "quantidade" INTEGER NOT NULL, PRIMARY KEY ("unidade_da_federacao", "atende_no_sus"));
CREATE TABLE "fonte_populacao" ("d1c" TEXT NOT NULL, "d1n" TEXT NOT NULL, "d3c" TEXT NOT NULL, "v" INTEGER NOT NULL, PRIMARY KEY ("d1c", "d3c"));
CREATE TABLE "perfil_uf" ("co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "populacao_estimada" INTEGER NOT NULL, "quantidade_ocorrencias" INTEGER NOT NULL, "quantidade_estabelecimentos" INTEGER NOT NULL, "leitos_existentes" INTEGER NOT NULL, "leitos_sus" INTEGER NOT NULL, "quantidade_equipes" INTEGER NOT NULL, "quantidade_registros_servicos" INTEGER NOT NULL, "quantidade_profissionais" INTEGER NOT NULL, "quantidade_profissionais_sus" INTEGER NOT NULL, PRIMARY KEY ("co_uf"));
CREATE TABLE "leitos_uf" ("co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "leitos_existentes" INTEGER NOT NULL, "leitos_sus" INTEGER NOT NULL, "uti_total_exist" INTEGER NOT NULL, "uti_total_sus" INTEGER NOT NULL, "populacao_estimada" INTEGER NOT NULL, "leitos_existentes_por_100_mil_habitantes" REAL NOT NULL, "leitos_sus_por_100_mil_habitantes" REAL NOT NULL, PRIMARY KEY ("co_uf"), FOREIGN KEY ("co_uf") REFERENCES "perfil_uf" ("co_uf"));
CREATE TABLE "leitos_brasil_mensal" ("comp" TEXT NOT NULL, "quantidade_registros_fonte" INTEGER NOT NULL, "leitos_existentes" INTEGER NOT NULL, "leitos_sus" INTEGER NOT NULL, "uti_total_exist" INTEGER NOT NULL, "uti_total_sus" INTEGER NOT NULL, "populacao_estimada" INTEGER NOT NULL, "leitos_existentes_por_100_mil_habitantes" REAL NOT NULL, "leitos_sus_por_100_mil_habitantes" REAL NOT NULL, "uti_total_exist_por_100_mil_habitantes" REAL NOT NULL, "uti_total_sus_por_100_mil_habitantes" REAL NOT NULL, PRIMARY KEY ("comp"));
CREATE TABLE "leitos_uf_mensal" ("comp" TEXT NOT NULL, "co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "leitos_existentes" INTEGER NOT NULL, "leitos_sus" INTEGER NOT NULL, "uti_total_exist" INTEGER NOT NULL, "uti_total_sus" INTEGER NOT NULL, "populacao_estimada" INTEGER NOT NULL, "leitos_existentes_por_100_mil_habitantes" REAL NOT NULL, "leitos_sus_por_100_mil_habitantes" REAL NOT NULL, "uti_total_exist_por_100_mil_habitantes" REAL NOT NULL, "uti_total_sus_por_100_mil_habitantes" REAL NOT NULL, PRIMARY KEY ("comp", "co_uf"), FOREIGN KEY ("co_uf") REFERENCES "perfil_uf" ("co_uf"));
CREATE TABLE "equipes_uf" ("co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "quantidade_equipes" INTEGER NOT NULL, "populacao_estimada" INTEGER NOT NULL, "equipes_por_100_mil_habitantes" REAL NOT NULL, PRIMARY KEY ("co_uf"), FOREIGN KEY ("co_uf") REFERENCES "perfil_uf" ("co_uf"));
CREATE TABLE "equipes_tipo" ("codigo_tipo_equipe" TEXT NOT NULL, "descricao_tipo_equipe" TEXT NOT NULL, "quantidade_equipes" INTEGER NOT NULL, PRIMARY KEY ("codigo_tipo_equipe"));
CREATE TABLE "equipes_uf_tipo" ("co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "codigo_tipo_equipe" TEXT NOT NULL, "descricao_tipo_equipe" TEXT NOT NULL, "quantidade_equipes" INTEGER NOT NULL, PRIMARY KEY ("co_uf", "codigo_tipo_equipe"), FOREIGN KEY ("co_uf") REFERENCES "perfil_uf" ("co_uf"));
CREATE TABLE "servicos_uf" ("co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "quantidade_registros_servicos" INTEGER NOT NULL, "populacao_estimada" INTEGER NOT NULL, "registros_servicos_por_100_mil_habitantes" REAL NOT NULL, PRIMARY KEY ("co_uf"), FOREIGN KEY ("co_uf") REFERENCES "perfil_uf" ("co_uf"));
CREATE TABLE "servicos_classificacao" ("codigo_classificacao_servico" TEXT NOT NULL, "codigo_servico" TEXT NOT NULL, "descricao_servico" TEXT NOT NULL, "descricao_classificacao_servico" TEXT NOT NULL, "quantidade_registros_servicos" INTEGER NOT NULL, PRIMARY KEY ("codigo_classificacao_servico"));
CREATE TABLE "servicos_uf_classificacao" ("co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "codigo_classificacao_servico" TEXT NOT NULL, "codigo_servico" TEXT NOT NULL, "descricao_servico" TEXT NOT NULL, "descricao_classificacao_servico" TEXT NOT NULL, "quantidade_registros_servicos" INTEGER NOT NULL, PRIMARY KEY ("co_uf", "codigo_classificacao_servico"), FOREIGN KEY ("co_uf") REFERENCES "perfil_uf" ("co_uf"));
CREATE TABLE "profissionais_uf" ("co_uf" TEXT NOT NULL, "nome_uf" TEXT NOT NULL, "quantidade_profissionais" INTEGER NOT NULL, "quantidade_profissionais_sus" INTEGER NOT NULL, "quantidade_profissionais_nao_sus" INTEGER NOT NULL, "populacao_estimada" INTEGER NOT NULL, "profissionais_por_100_mil_habitantes" REAL NOT NULL, "proporcao_profissionais_sus" REAL NOT NULL, PRIMARY KEY ("co_uf"), FOREIGN KEY ("co_uf") REFERENCES "perfil_uf" ("co_uf"));
CREATE TABLE "estabelecimentos_tipo" ("tp_unidade" TEXT NOT NULL, "descricao" TEXT NOT NULL, "quantidade_estabelecimentos" INTEGER NOT NULL, PRIMARY KEY ("tp_unidade"));
CREATE TABLE "estabelecimentos_gestao" ("tp_gestao" TEXT NOT NULL, "descricao" TEXT NOT NULL, "quantidade_estabelecimentos" INTEGER NOT NULL, PRIMARY KEY ("tp_gestao"));
CREATE TABLE "controles_qualidade" ("id_controle" TEXT NOT NULL, "descricao_controle" TEXT NOT NULL, "dimensao" TEXT NOT NULL, "severidade" TEXT NOT NULL, "situacao" TEXT NOT NULL, "quantidade_avaliada" INTEGER NOT NULL, "quantidade_falhas" INTEGER NOT NULL, "proporcao_falhas" REAL NOT NULL, PRIMARY KEY ("id_controle"));
CREATE TABLE "__metadados" ("chave" TEXT PRIMARY KEY, "valor" TEXT NOT NULL);
